:root {
  /* Light theme colors */
  --color-bg: #ffffff;
  --color-text: #1a1a1a;
  --color-primary: #005a9c;
  --color-primary-hover: #004578;
  --color-secondary: #0078d4;
  --color-secondary-hover: #005a9c;
  --color-border: #cccccc;
  --color-error: #b00020;
  --color-success: #107c10;
}

@media (prefers-color-scheme: dark) {
  :root {
    /* Dark theme colors */
    --color-bg: #121212;
    --color-text: #e1e1e1;
    --color-primary: #3399ff;
    --color-primary-hover: #66b2ff;
    --color-secondary: #80caff;
    --color-secondary-hover: #a3d4ff;
    --color-border: #333333;
    --color-error: #cf6679;
    --color-success: #4caf50;
  }
}

/* Smooth transitions for color changes */
:root {
  transition: 
    --color-bg 0.3s ease,
    --color-text 0.3s ease,
    --color-primary 0.3s ease,
    --color-primary-hover 0.3s ease,
    --color-secondary 0.3s ease,
    --color-secondary-hover 0.3s ease,
    --color-border 0.3s ease,
    --color-error 0.3s ease,
    --color-success 0.3s ease;
}

/* Disable animations and transitions for users who prefer reduced motion */
@media (prefers-reduced-motion: reduce) {
  :root {
    transition: none !important;
  }
}

