// src/utils/themeDetection.js

/**
 * Detects the user's preferred color scheme (dark or light) based on system settings.
 * Falls back gracefully if CSS custom properties are unsupported.
 *
 * Returns:
 *   'dark'  - if user prefers dark mode
 *   'light' - if user prefers light mode or no preference detected
 */

function supportsCSSCustomProperties() {
  return window.CSS && window.CSS.supports && window.CSS.supports('--fake-var', 0);
}

function getSystemThemePreference() {
  if (window.matchMedia) {
    if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      return 'dark';
    }
    if (window.matchMedia('(prefers-color-scheme: light)').matches) {
      return 'light';
    }
  }
  return null;
}

function detectTheme() {
  if (!supportsCSSCustomProperties()) {
    // If CSS custom properties are not supported, fallback to light theme
    return 'light';
  }

  // Try to detect system preference
  const systemPref = getSystemThemePreference();
  if (systemPref === 'dark' || systemPref === 'light') {
    return systemPref;
  }

  // Default fallback
  return 'light';
}

export default detectTheme;

