import React from 'react';

const style = `
  .query-editor {
    background-color: var(--qe-bg, #fff);
    color: var(--qe-fg, #000);
    font-family: monospace;
    padding: 1rem;
    border-radius: 4px;
    white-space: pre-wrap;
    word-break: break-word;
    font-size: 14px;
  }
  .query-editor .keyword {
    color: var(--qe-keyword, #0070f3);
    font-weight: 600;
  }
  .query-editor .string {
    color: var(--qe-string, #d14);
  }
  .query-editor .comment {
    color: var(--qe-comment, #6a9955);
    font-style: italic;
  }
  .query-editor .number {
    color: var(--qe-number, #098658);
  }
  .query-editor .operator {
    color: var(--qe-operator, #333);
  }
`;

const keywords = [
  'select', 'from', 'where', 'and', 'or', 'not', 'insert', 'update', 'delete',
  'create', 'drop', 'alter', 'table', 'into', 'values', 'set', 'join', 'on',
  'group', 'by', 'order', 'limit', 'as', 'in', 'is', 'null', 'like', 'distinct'
];

const operators = ['=', '>', '<', '>=', '<=', '<>', '!=', '+', '-', '*', '/', '%'];

function escapeHtml(text) {
  return text.replace(/[&<>"']/g, m => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  })[m]);
}

function tokenize(text) {
  const tokens = [];
  let pos = 0;
  const len = text.length;

  while (pos < len) {
    const char = text[pos];

    // Comments (single line starting with # or --)
    if (char === '#') {
      const commentText = text.slice(pos);
      tokens.push({ type: 'comment', value: commentText });
      break;
    }
    if (char === '-' && text[pos + 1] === '-') {
      const endOfLine = text.indexOf('\n', pos);
      const commentText = endOfLine === -1 ? text.slice(pos) : text.slice(pos, endOfLine);
      tokens.push({ type: 'comment', value: commentText });
      pos += commentText.length;
      continue;
    }

    // Strings (single or double quoted)
    if (char === '\'' || char === '"') {
      const quoteType = char;
      let endPos = pos + 1;
      let escaped = false;
      while (endPos < len) {
        if (text[endPos] === '\\' && !escaped) {
          escaped = true;
          endPos++;
          continue;
        }
        if (text[endPos] === quoteType && !escaped) {
          break;
        }
        escaped = false;
        endPos++;
      }
      const str = text.slice(pos, endPos + 1);
      tokens.push({ type: 'string', value: str });
      pos = endPos + 1;
      continue;
    }

    // Numbers
    if (/\d/.test(char)) {
      let endPos = pos + 1;
      while (endPos < len && /[\d\.]/.test(text[endPos])) {
        endPos++;
      }
      const num = text.slice(pos, endPos);
      tokens.push({ type: 'number', value: num });
      pos = endPos;
      continue;
    }

    // Operators
    let opMatched = false;
    for (const op of operators) {
      if (text.startsWith(op, pos)) {
        tokens.push({ type: 'operator', value: op });
        pos += op.length;
        opMatched = true;
        break;
      }
    }
    if (opMatched) continue;

    // Words (keywords or identifiers)
    if (/[a-zA-Z_]/.test(char)) {
      let endPos = pos + 1;
      while (endPos < len && /[a-zA-Z0-9_]/.test(text[endPos])) {
        endPos++;
      }
      const word = text.slice(pos, endPos);
      if (keywords.includes(word.toLowerCase())) {
        tokens.push({ type: 'keyword', value: word });
      } else {
        tokens.push({ type: 'text', value: word });
      }
      pos = endPos;
      continue;
    }

    // Whitespace or other single characters
    tokens.push({ type: 'text', value: char });
    pos++;
  }

  return tokens;
}

export default function QueryEditorSyntaxHighlighting({ query }) {
  const tokens = React.useMemo(() => tokenize(query), [query]);

  return (
    <>
      <style>{style}</style>
      <pre className="query-editor" aria-label="Query editor with syntax highlighting">
        {tokens.map((token, i) => {
          if (token.type === 'text') {
            return <span key={i}>{token.value}</span>;
          }
          return (
            <span key={i} className={token.type}>
              {token.value}
            </span>
          );
        })}
      </pre>
    </>
  );
}

