import React, { useContext, useMemo } from 'react';

// Assuming there is a ThemeContext providing current theme info
// If not, you can replace this with your actual theme provider/context
const ThemeContext = React.createContext({
  theme: 'light', // 'light' or 'dark'
  colors: {
    light: {
      primary: '#1976d2',
      secondary: '#9c27b0',
      background: '#ffffff',
      text: '#000000',
      chartColors: [
        '#1976d2',
        '#9c27b0',
        '#ff9800',
        '#4caf50',
        '#f44336',
        '#00bcd4',
        '#cddc39',
      ],
    },
    dark: {
      primary: '#90caf9',
      secondary: '#ce93d8',
      background: '#121212',
      text: '#ffffff',
      chartColors: [
        '#90caf9',
        '#ce93d8',
        '#ffb74d',
        '#81c784',
        '#e57373',
        '#4dd0e1',
        '#dce775',
      ],
    },
  },
});

/**
 * Hook to get adapted colors for data visualizations based on active theme.
 * Returns an object with colors to be used in charts.
 */
export function useDataVisualizationColors() {
  const { theme, colors } = useContext(ThemeContext);

  // Memoize to avoid recalculations on every render
  const adaptedColors = useMemo(() => {
    const themeColors = colors[theme] || colors.light;

    return {
      primary: themeColors.primary,
      secondary: themeColors.secondary,
      background: themeColors.background,
      text: themeColors.text,
      chartColors: themeColors.chartColors,
    };
  }, [theme, colors]);

  return adaptedColors;
}

/**
 * Higher Order Component to inject theme-adapted colors into a data visualization component.
 * The wrapped component will receive a `themeColors` prop with adapted colors.
 * 
 * Usage:
 * const ThemedChart = withDataVisualizationTheme(ChartComponent);
 */
export function withDataVisualizationTheme(Component) {
  return function ThemedComponent(props) {
    const themeColors = useDataVisualizationColors();
    return <Component {...props} themeColors={themeColors} />;
  };
}

/**
 * DataVisualizationThemeAdapter component that uses render props pattern.
 * It provides theme-adapted colors to its child function.
 * 
 * Usage:
 * <DataVisualizationThemeAdapter>
 *   {(themeColors) => <ChartComponent themeColors={themeColors} />}
 * </DataVisualizationThemeAdapter>
 */
export function DataVisualizationThemeAdapter({ children }) {
  const themeColors = useDataVisualizationColors();
  return children(themeColors);
}

export default DataVisualizationThemeAdapter;
